import 'dart:isolate';

int jumlahPrima(int batas) {
  var n = 0;
  for (var i = 2; i <= batas; i++) {
    var prima = true;
    for (var j = 2; j * j <= i; j++) {
      if (i % j == 0) {
        prima = false;
        break;
      }
    }
    if (prima) n++;
  }
  return n;
}

Future<void> main() async {
  final hasil = await Isolate.run(() => jumlahPrima(2000000));
  print('ada $hasil bilangan prima');
}

