def token(teks):
    return teks.replace("(", " ( ").replace(")", " ) ").split()


def baca(t):
    x = t.pop(0)
    if x == "(":
        daftar = []
        while t[0] != ")":
            daftar.append(baca(t))
        t.pop(0)
        return daftar
    return int(x) if x.lstrip("-").isdigit() else x


OPERATOR = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
            "*": lambda a, b: a * b}


def hitung(x):
    if isinstance(x, int):
        return x
    op, *arg = x
    nilai = [hitung(a) for a in arg]
    hasil = nilai[0]
    for v in nilai[1:]:
        hasil = OPERATOR[op](hasil, v)
    return hasil


