const Pengguna = struct {
    nama: []u8,
    skor: []u32,
};

fn buatPengguna(alokator: std.mem.Allocator, nama: []const u8) !Pengguna {
    const salinan = try alokator.dupe(u8, nama);
    errdefer alokator.free(salinan);

    const skor = try alokator.alloc(u32, 3);
    @memset(skor, 0);
    return .{ .nama = salinan, .skor = skor };
}

