import re
import sys

TOKEN = re.compile(r'\s*("[^"]*"|\d+|true|false|==|and|[-+*])')

ATURAN = {
    ("int", "+", "int"): "int",
    ("int", "-", "int"): "int",
    ("int", "*", "int"): "int",
    ("str", "+", "str"): "str",
    ("int", "==", "int"): "bool",
    ("str", "==", "str"): "bool",
    ("bool", "==", "bool"): "bool",
    ("bool", "and", "bool"): "bool",
}


def tipe_literal(t):
    if t.startswith('"'):
        return "str"
    if t.isdigit():
        return "int"
    if t in ("true", "false"):
        return "bool"
    return None


def periksa(baris):
    token, pos = [], 0
    while pos < len(baris):
        m = TOKEN.match(baris, pos)
        if not m:
            return "galat sintaks"
        token.append(m.group(1))
        pos = m.end()
    if len(token) != 3:
        return "galat sintaks"
    kiri, op, kanan = token
    tk, tn = tipe_literal(kiri), tipe_literal(kanan)
    if tk is None or tn is None or tipe_literal(op) is not None:
        return "galat sintaks"
    hasil = ATURAN.get((tk, op, tn))
    if hasil is None:
        return f"galat tipe: {tk} {op} {tn}"
    return hasil


