import json
import re
import sys


class NilPaksa(Exception):
    pass


def tampil(v):
    if v is None:
        return "nil"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, str):
        return v
    if isinstance(v, (dict, list)):
        return json.dumps(v, ensure_ascii=False)
    return str(v)


def evaluasi(data, jalur):
    potong = re.split(r"(\?\.|!\.)", jalur.strip())
    nama = potong[0]
    v = data.get(nama)
    for i in range(1, len(potong), 2):
        tanda, kunci = potong[i], potong[i + 1]
        if v is None:
            if tanda == "?.":
                return None
            raise NilPaksa(nama)
        v = v.get(kunci) if isinstance(v, dict) else None
        nama = kunci
    return v


