from dataclasses import dataclass


@dataclass
class Lingkaran:
    r: float


@dataclass
class Persegi:
    sisi: float


@dataclass
class Segitiga:
    a: float
    b: float
    c: float


def buat(nama, angka):
    match nama:
        case 'lingkaran':
            return Lingkaran(*angka)
        case 'persegi':
            return Persegi(*angka)
        case 'segitiga':
            return Segitiga(*angka)
    return None


def kategori(luas):
    if luas >= 20:
        return 'besar'
    if luas >= 10:
        return 'sedang'
    return 'kecil'


def jelaskan(b):
    match b:
        case Lingkaran(r):
            luas, nama = math.pi * r * r, 'lingkaran'
        case Persegi(s):
            luas, nama = s * s, 'persegi'
        case Segitiga(a, b, c) if max(a, b, c) >= a + b + c - max(a, b, c):
            return 'segitiga: tidak sah'
        case Segitiga(a, b, c):
            s = (a + b + c) / 2
            luas = math.sqrt(s * (s - a) * (s - b) * (s - c))
            nama = 'segitiga'
    return f'{nama}: luas {luas:.2f} ({kategori(luas)})'


