import re
import sys

TUJUAN = re.compile(r'(\w+)\(([^()]*)\)')


def urai(teks):
    return [(n, [a.strip() for a in arg.split(',')])
            for n, arg in TUJUAN.findall(teks)]


def variabel(x):
    return x[:1].isupper() or x[:1] == '_'


def telusur(x, s):
    while variabel(x) and x in s:
        x = s[x]
    return x


def unifikasi(a, b, s):
    if a[0] != b[0] or len(a[1]) != len(b[1]):
        return None
    s = dict(s)
    for x, y in zip(a[1], b[1]):
        x, y = telusur(x, s), telusur(y, s)
        if x == y:
            continue
        if variabel(x):
            s[x] = y
        elif variabel(y):
            s[y] = x
        else:
            return None
    return s


