    ubah = lambda t: (t[0], [f'{a}_{nomor[0]}' if variabel(a) else a
                              for a in t[1]])
    return ubah(kepala), [ubah(t) for t in badan]


def selesaikan(tujuan, s):
    if not tujuan:
        yield s
        return
    pertama, sisa = tujuan[0], tujuan[1:]
    for kepala, badan in klausa:
