else:
    jalankan(*hasil)

import re
import sys

lembar = {}


def ke_angka(huruf):
    n = 0
    for h in huruf:
        n = n * 26 + (ord(h) - ord("A") + 1)
    return n


def ke_huruf(n):
    huruf = ""
    while n > 0:
        n, sisa = divmod(n - 1, 26)
        huruf = chr(ord("A") + sisa) + huruf
    return huruf


def urai_alamat(teks):
    m = re.fullmatch(r"([A-Za-z]{1,3})([0-9]+)", teks.strip())
    if not m or int(m.group(2)) == 0:
        raise ValueError(f"alamat '{teks.strip()}' tidak sah")
    return int(m.group(2)), ke_angka(m.group(1).upper())


def alamat(baris, kolom):
    return f"{ke_huruf(kolom)}{baris}"


def tampil(baris, kolom):
    return lembar.get((baris, kolom), "(kosong)")


def jumlah(awal, akhir):
    (b1, k1), (b2, k2) = urai_alamat(awal), urai_alamat(akhir)
    total = 0
    for b in range(min(b1, b2), max(b1, b2) + 1):
        for k in range(min(k1, k2), max(k1, k2) + 1):
            isi = lembar.get((b, k), "")
            if re.fullmatch(r"-?[0-9]+", isi):
                total += int(isi)
    return total


