import re
import sys

TOKEN = re.compile(r"\s*([A-Za-z_][A-Za-z0-9_]*|[~&|^()])")


class Galat(Exception):
    pass


def pecah(teks):
    token, pos = [], 0
    teks = teks.strip()
    while pos < len(teks):
        m = TOKEN.match(teks, pos)
        if not m:
            raise Galat(f"karakter tidak dikenal '{teks[pos:].strip()[0]}'")
        token.append(m.group(1))
        pos = m.end()
    return token


class Pengurai:
    # prioritas Verilog: ~ paling kuat, lalu &, lalu ^, lalu |
    def __init__(self, token):
        self.t, self.i = token, 0

    def lihat(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def ambil(self):
        x = self.lihat()
        self.i += 1
        return x

    def urai(self):
        pohon = self.atau()
        if self.lihat() is not None:
            raise Galat(f"token tak terduga '{self.lihat()}'")
        return pohon

    def biner(self, op, lanjut):
        kiri = lanjut()
        while self.lihat() == op:
            self.ambil()
            kiri = (op, kiri, lanjut())
        return kiri

    def atau(self):
        return self.biner("|", self.xor)

    def xor(self):
        return self.biner("^", self.dan)

    def dan(self):
        return self.biner("&", self.satu)

    def satu(self):
        x = self.ambil()
        if x == "~":
            return ("~", self.satu())
        if x == "(":
            isi = self.atau()
            if self.ambil() != ")":
                raise Galat("kurung tidak ditutup")
            return isi
        if x is None:
            raise Galat("rumus tidak lengkap")
        if not re.fullmatch(r"[A-Za-z_]\w*", x):
            raise Galat(f"token tak terduga '{x}'")
        return x


def nama_di(pohon):
    if isinstance(pohon, str):
        return {pohon}
    return set().union(*(nama_di(p) for p in pohon[1:]))


def baca(teks):
    masuk, keluar, kabel, rumus = [], [], [], {}
    for baris in teks.split(";"):
        baris = re.sub(r"^\s*module\s+\w+", "", baris).strip()
        if not baris or baris == "endmodule":
            continue
        kata = baris.split(None, 1)
        if kata[0] in ("input", "output", "wire"):
            nama = [n.strip() for n in kata[1].split(",")]
            {"input": masuk, "output": keluar, "wire": kabel}[kata[0]].extend(nama)
        elif kata[0] == "assign":
            kiri, kanan = kata[1].split("=", 1)
            rumus[kiri.strip()] = Pengurai(pecah(kanan)).urai()
        else:
            raise Galat(f"baris tidak dikenal '{baris}'")
    dikenal = set(masuk) | set(keluar) | set(kabel)
    for kiri, pohon in rumus.items():
        for n in sorted({kiri} | nama_di(pohon)):
            if n not in dikenal:
                raise Galat(f"sinyal '{n}' belum dideklarasikan")
    for k in keluar:
        if k not in rumus:
            raise Galat(f"output '{k}' tidak pernah di-assign")
    return masuk, keluar, rumus


def hitung(pohon, nilai, rumus, jalur):
    if isinstance(pohon, str):
        if pohon in nilai:
            return nilai[pohon]
        if pohon in jalur:
            raise Galat(f"rangkaian melingkar pada '{pohon}'")
        if pohon not in rumus:
            raise Galat(f"sinyal '{pohon}' tidak punya nilai")
        nilai[pohon] = hitung(rumus[pohon], nilai, rumus, jalur | {pohon})
        return nilai[pohon]
    if pohon[0] == "~":
        return 1 - hitung(pohon[1], nilai, rumus, jalur)
    a = hitung(pohon[1], nilai, rumus, jalur)
    b = hitung(pohon[2], nilai, rumus, jalur)
    return {"&": a & b, "|": a | b, "^": a ^ b}[pohon[0]]


try:
    teks = "\n".join(b.split("//")[0] for b in sys.stdin.read().splitlines())
    masuk, keluar, rumus = baca(teks)
    baris_hasil = []
    for angka in range(2 ** len(masuk)):
        nilai = {n: (angka >> (len(masuk) - 1 - i)) & 1 for i, n in enumerate(masuk)}
        hasil = [hitung(k, nilai, rumus, frozenset()) for k in keluar]
        baris_hasil.append(([nilai[n] for n in masuk], hasil))
except Galat as g:
    print(f"galat: {g}")
else:
    lebar = [len(n) for n in masuk + keluar]
    print(" ".join(masuk) + " | " + " ".join(keluar))
    for kiri, kanan in baris_hasil:
        sel = [str(v).ljust(w) for v, w in zip(kiri + kanan, lebar)]
        print(" ".join(sel[:len(masuk)]) + " | " + " ".join(sel[len(masuk):]).rstrip())

