import re
import sys


class Galat(Exception):
    pass


def pecah(teks):
    token = re.findall(r"[A-Za-z_]\w*|[01]|[()]|\S", teks)
    for t in token:
        if not re.fullmatch(r"[A-Za-z_]\w*|[01]|[()]", t):
            raise Galat(f"karakter tidak dikenal '{t}'")
    return token


def urai(token):
    # or paling lemah, lalu and, lalu not
    pos = 0

    def lihat():
        return token[pos] if pos < len(token) else None

    def ambil():
        nonlocal pos
        pos += 1
        return token[pos - 1] if pos <= len(token) else None

    def atau():
        kiri = dan()
        while lihat() == "or":
            ambil()
            kiri = ("or", kiri, dan())
        return kiri

    def dan():
        kiri = bukan()
        while lihat() == "and":
            ambil()
            kiri = ("and", kiri, bukan())
        return kiri

    def bukan():
        x = ambil()
        if x == "not":
            return ("not", bukan())
        if x == "(":
            isi = atau()
            if ambil() != ")":
                raise Galat("kurung tidak ditutup")
            return isi
        if x in ("0", "1"):
            return int(x)
        if x is None:
            raise Galat("rumus tidak lengkap")
        if x in ("and", "or", ")"):
            raise Galat(f"token tak terduga '{x}'")
        return x

    pohon = atau()
    if lihat() is not None:
        raise Galat(f"token tak terduga '{lihat()}'")
    return pohon


def nilai(pohon, memori):
    if isinstance(pohon, int):
        return pohon
    if isinstance(pohon, str):
        return memori.get(pohon, 0)
    if pohon[0] == "not":
        return 1 - nilai(pohon[1], memori)
    a, b = nilai(pohon[1], memori), nilai(pohon[2], memori)
    return a & b if pohon[0] == "and" else a | b


teks = sys.stdin.read().split("---")
try:
    if len(teks) != 2:
        raise Galat("butuh tepat satu pemisah ---")
