import sys

sys.setrecursionlimit(10000)

KATA_KUNCI = {"let", "print", "if", "else", "while", "fn", "return",
              "and", "or", "not", "true", "false"}
SIMBOL2 = {"==", "!=", "<=", ">="}
SIMBOL1 = set("+-*/%<>=(){},;")
BATAS_PUTARAN = 100000
BATAS_REKURSI = 100


class Galat(Exception):
    def __init__(self, baris, pesan):
        super().__init__(pesan)
        self.baris = baris


class Kembali(Exception):
    def __init__(self, nilai):
        self.nilai = nilai


# ------------------------------------------------------------ tokenizer

def tokenize(teks):
    token, i, baris = [], 0, 1
    while i < len(teks):
        c = teks[i]
        if c == "\n":
            baris += 1
            i += 1
        elif c in " \t\r":
            i += 1
        elif c == "#":
            while i < len(teks) and teks[i] != "\n":
                i += 1
        elif c.isdigit():
            j = i
            while j < len(teks) and teks[j].isdigit():
                j += 1
            token.append(("angka", int(teks[i:j]), baris))
            i = j
        elif c.isalpha() or c == "_":
            j = i
            while j < len(teks) and (teks[j].isalnum() or teks[j] == "_"):
                j += 1
            kata = teks[i:j]
            token.append(("kunci" if kata in KATA_KUNCI else "nama", kata, baris))
            i = j
        elif c == '"':
            j = teks.find('"', i + 1)
            if j == -1 or "\n" in teks[i:j]:
                raise Galat(baris, "string tidak ditutup")
            token.append(("teks", teks[i + 1:j], baris))
            i = j + 1
        elif teks[i:i + 2] in SIMBOL2:
            token.append(("simbol", teks[i:i + 2], baris))
            i += 2
        elif c in SIMBOL1:
            token.append(("simbol", c, baris))
            i += 1
        else:
            raise Galat(baris, f"karakter tidak dikenal '{c}'")
    token.append(("akhir", None, baris))
    return token


# --------------------------------------------------------------- parser

class Parser:
    def __init__(self, token):
        self.t, self.i = token, 0

    def lihat(self, nilai=None):
        jenis, isi, _ = self.t[self.i]
        if nilai is None:
            return jenis != "akhir"
        return isi == nilai and jenis in ("simbol", "kunci")

    def baris(self):
        return self.t[self.i][2]

    def maju(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def harus(self, nilai):
        jenis, isi, baris = self.t[self.i]
        if isi != nilai or jenis not in ("simbol", "kunci"):
            tampil = "akhir program" if jenis == "akhir" else f"'{isi}'"
            raise Galat(baris, f"diharapkan '{nilai}', ditemukan {tampil}")
        self.i += 1

    def nama(self):
        jenis, isi, baris = self.maju()
        if jenis != "nama":
            raise Galat(baris, f"diharapkan nama, ditemukan '{isi}'")
        return isi

    def program(self):
        hasil = []
        while self.lihat():
            hasil.append(self.pernyataan())
        return hasil

    def blok(self):
        self.harus("{")
        hasil = []
        while not self.lihat("}"):
            if not self.lihat():
                raise Galat(self.baris(), "blok tidak ditutup '}'")
            hasil.append(self.pernyataan())
        self.harus("}")
        return hasil

    def pernyataan(self):
        b = self.baris()
        if self.lihat("let"):
            self.maju()
            nama = self.nama()
            self.harus("=")
            ekspr = self.ekspresi()
            self.harus(";")
            return ("let", b, nama, ekspr)
        if self.lihat("print"):
            self.maju()
            ekspr = self.ekspresi()
            self.harus(";")
            return ("print", b, ekspr)
        if self.lihat("if"):
            self.maju()
            self.harus("(")
            syarat = self.ekspresi()
            self.harus(")")
            ya = self.blok()
            tidak = []
            if self.lihat("else"):
                self.maju()
                tidak = [self.pernyataan()] if self.lihat("if") else self.blok()
            return ("if", b, syarat, ya, tidak)
        if self.lihat("while"):
            self.maju()
            self.harus("(")
            syarat = self.ekspresi()
            self.harus(")")
            return ("while", b, syarat, self.blok())
        if self.lihat("fn"):
            self.maju()
            nama = self.nama()
            self.harus("(")
            param = []
            if not self.lihat(")"):
                param.append(self.nama())
                while self.lihat(","):
                    self.maju()
                    param.append(self.nama())
            self.harus(")")
            return ("fn", b, nama, param, self.blok())
        if self.lihat("return"):
            self.maju()
            ekspr = self.ekspresi()
            self.harus(";")
            return ("return", b, ekspr)
        if self.t[self.i][0] == "nama" and self.t[self.i + 1][1] == "=" \
                and self.t[self.i + 1][0] == "simbol":
            nama = self.nama()
            self.maju()
            ekspr = self.ekspresi()
            self.harus(";")
            return ("set", b, nama, ekspr)
        ekspr = self.ekspresi()
        self.harus(";")
        return ("ekspr", b, ekspr)

    # prioritas: or < and < not < perbandingan < + - < * / % < unary -
    def ekspresi(self):
        return self.atau()

    def biner(self, ops, lanjut):
        kiri = lanjut()
        while any(self.lihat(op) for op in ops):
            jenis, op, b = self.maju()
            kiri = ("op", b, op, kiri, lanjut())
        return kiri

    def atau(self):
        return self.biner(["or"], self.dan)

    def dan(self):
        return self.biner(["and"], self.bukan)

    def bukan(self):
        if self.lihat("not"):
            b = self.maju()[2]
            return ("not", b, self.bukan())
        return self.banding()

    def banding(self):
        return self.biner(["==", "!=", "<", "<=", ">", ">="], self.jumlah)

    def jumlah(self):
        return self.biner(["+", "-"], self.kali)

    def kali(self):
        return self.biner(["*", "/", "%"], self.unari)

    def unari(self):
        if self.lihat("-"):
            b = self.maju()[2]
            return ("neg", b, self.unari())
        return self.primer()

    def primer(self):
        jenis, isi, b = self.maju()
        if jenis in ("angka", "teks"):
            return ("nilai", b, isi)
        if jenis == "kunci" and isi in ("true", "false"):
            return ("nilai", b, isi == "true")
        if jenis == "nama":
            if self.lihat("("):
                self.maju()
                arg = []
                if not self.lihat(")"):
                    arg.append(self.ekspresi())
                    while self.lihat(","):
                        self.maju()
                        arg.append(self.ekspresi())
                self.harus(")")
                return ("panggil", b, isi, arg)
            return ("var", b, isi)
        if jenis == "simbol" and isi == "(":
            ekspr = self.ekspresi()
            self.harus(")")
            return ekspr
        tampil = "akhir program" if jenis == "akhir" else f"'{isi}'"
        raise Galat(b, f"token tak terduga {tampil}")


# ------------------------------------------------------------ evaluator

class Lingkup:
    def __init__(self, induk=None):
        self.isi, self.induk = {}, induk

    def cari(self, nama):
        lingkup = self
        while lingkup is not None:
            if nama in lingkup.isi:
                return lingkup
            lingkup = lingkup.induk
        return None


def tampil(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if v is None:
        return "nil"
    return str(v)


def jenis(v):
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, str):
        return "string"
    return "nil"


class Mesin:
    def __init__(self):
        self.global_ = Lingkup()
        self.fungsi = {}
        self.dalam = 0

    def jalankan(self, daftar, lingkup):
        for p in daftar:
            self.satu(p, lingkup)

    def satu(self, p, lingkup):
        jenis_p, b = p[0], p[1]
        if jenis_p == "let":
            lingkup.isi[p[2]] = self.nilai(p[3], lingkup)
        elif jenis_p == "set":
            tempat = lingkup.cari(p[2])
            if tempat is None:
                raise Galat(b, f"variabel '{p[2]}' belum didefinisikan")
            tempat.isi[p[2]] = self.nilai(p[3], lingkup)
        elif jenis_p == "print":
            print(tampil(self.nilai(p[2], lingkup)))
        elif jenis_p == "if":
            cabang = p[3] if self.syarat(p[2], lingkup, b) else p[4]
            self.jalankan(cabang, Lingkup(lingkup))
        elif jenis_p == "while":
            putaran = 0
            while self.syarat(p[2], lingkup, b):
                putaran += 1
                if putaran > BATAS_PUTARAN:
                    raise Galat(b, f"perulangan lebih dari {BATAS_PUTARAN} putaran")
                self.jalankan(p[3], Lingkup(lingkup))
        elif jenis_p == "fn":
            self.fungsi[p[2]] = (p[3], p[4])
        elif jenis_p == "return":
            if self.dalam == 0:
                raise Galat(b, "return di luar fungsi")
            raise Kembali(self.nilai(p[2], lingkup))
        else:
            self.nilai(p[2], lingkup)

    def syarat(self, ekspr, lingkup, b):
        v = self.nilai(ekspr, lingkup)
        if not isinstance(v, bool):
            raise Galat(b, f"kondisi harus bool, bukan {jenis(v)}")
        return v

    def nilai(self, e, lingkup):
        jenis_e, b = e[0], e[1]
        if jenis_e == "nilai":
            return e[2]
        if jenis_e == "var":
            tempat = lingkup.cari(e[2])
            if tempat is None:
                raise Galat(b, f"variabel '{e[2]}' belum didefinisikan")
            return tempat.isi[e[2]]
        if jenis_e == "neg":
            v = self.nilai(e[2], lingkup)
            if jenis(v) != "int":
                raise Galat(b, f"tipe tidak cocok untuk '-': {jenis(v)}")
            return -v
        if jenis_e == "not":
            v = self.nilai(e[2], lingkup)
            if not isinstance(v, bool):
                raise Galat(b, f"tipe tidak cocok untuk 'not': {jenis(v)}")
            return not v
        if jenis_e == "panggil":
            return self.panggil(e, lingkup)
        op = e[2]
        if op in ("and", "or"):
            kiri = self.nilai(e[3], lingkup)
            if not isinstance(kiri, bool):
                raise Galat(b, f"tipe tidak cocok untuk '{op}': {jenis(kiri)}")
            if (op == "and" and not kiri) or (op == "or" and kiri):
                return kiri
            kanan = self.nilai(e[4], lingkup)
            if not isinstance(kanan, bool):
                raise Galat(b, f"tipe tidak cocok untuk '{op}': {jenis(kanan)}")
            return kanan
        a, c = self.nilai(e[3], lingkup), self.nilai(e[4], lingkup)
        ja, jc = jenis(a), jenis(c)
        if op in ("==", "!="):
            sama = ja == jc and a == c
            return sama if op == "==" else not sama
        if op == "+" and ja == jc == "string":
            return a + c
        if op in ("<", "<=", ">", ">=") and ja == jc and ja in ("int", "string"):
            return {"<": a < c, "<=": a <= c, ">": a > c, ">=": a >= c}[op]
        if ja != "int" or jc != "int":
            raise Galat(b, f"tipe tidak cocok untuk '{op}': {ja} dan {jc}")
        if op in ("/", "%") and c == 0:
            raise Galat(b, "bagi dengan nol")
        return {"+": a + c, "-": a - c, "*": a * c, "/": a // c, "%": a % c}[op]

    def panggil(self, e, lingkup):
        b, nama, arg = e[1], e[2], e[3]
        if nama not in self.fungsi:
            raise Galat(b, f"fungsi '{nama}' belum didefinisikan")
        param, badan = self.fungsi[nama]
        if len(arg) != len(param):
            raise Galat(b, f"{nama} butuh {len(param)} argumen, diberi {len(arg)}")
        nilai_arg = [self.nilai(a, lingkup) for a in arg]
        if self.dalam >= BATAS_REKURSI:
            raise Galat(b, f"rekursi lebih dari {BATAS_REKURSI} tingkat")
        lokal = Lingkup(self.global_)
        lokal.isi.update(zip(param, nilai_arg))
        self.dalam += 1
        try:
            self.jalankan(badan, lokal)
        except Kembali as k:
            return k.nilai
        finally:
            self.dalam -= 1
        return None


def main():
    try:
        program = Parser(tokenize(sys.stdin.read())).program()
        mesin = Mesin()
        mesin.jalankan(program, mesin.global_)
    except Galat as g:
        print(f"galat baris {g.baris}: {g}")


main()

